int search_rotated(const int *a, size_t n, int target){
    if(!a||n==0)return -1;
    size_t lo=0,hi=n-1;
    while(lo<=hi){
        size_t mid=lo+(hi-lo)/2;
        if(a[mid]==target)return (int)mid;
        if(a[lo]<=a[mid]){
            if(a[lo]<=target&&target<a[mid]){ if(mid==0) break; hi=mid-1; }
            else lo=mid+1;
        } else {
            if(a[mid]<target&&target<=a[hi]) lo=mid+1;
            else { if(mid==0) break; hi=mid-1; }
        }
    }
    return -1;
}

static void merge_run(int *a,int *tmp,size_t lo,size_t mid,size_t hi){
    size_t i=lo,j=mid,k=lo;
    while(i<mid&&j<hi){ if(a[i]<=a[j]) tmp[k++]=a[i++]; else tmp[k++]=a[j++]; }
    while(i<mid) tmp[k++]=a[i++];
    while(j<hi)  tmp[k++]=a[j++];
    for(size_t t=lo;t<hi;t++) a[t]=tmp[t];
}
static void merge_rec(int *a,int *tmp,size_t lo,size_t hi){
    if(hi-lo<2)return;
    size_t mid=lo+(hi-lo)/2;
    merge_rec(a,tmp,lo,mid); merge_rec(a,tmp,mid,hi);
    merge_run(a,tmp,lo,mid,hi);
}
void merge_sort(int *a, size_t n){
    if(!a||n<2)return;
    int *tmp=malloc(n*sizeof *tmp);
    if(!tmp)return;
    merge_rec(a,tmp,0,n);
    free(tmp);
}

static void swap_int(int *x,int *y){ int t=*x; *x=*y; *y=t; }
static size_t lomuto_partition(int *a,size_t lo,size_t hi){
    size_t mid=lo+(hi-lo)/2;
    if(a[mid]<a[lo]) swap_int(&a[mid],&a[lo]);
    if(a[hi]<a[lo])  swap_int(&a[hi],&a[lo]);
    if(a[hi]<a[mid]) swap_int(&a[hi],&a[mid]);
    swap_int(&a[mid],&a[hi]);
    int pivot=a[hi]; size_t i=lo;
    for(size_t j=lo;j<hi;j++) if(a[j]<pivot) swap_int(&a[i++],&a[j]);
    swap_int(&a[i],&a[hi]);
    return i;
}
static void quick_rec(int *a,size_t lo,size_t hi){
    while(lo<hi){
        size_t p=lomuto_partition(a,lo,hi);
        if(p-lo<hi-p){ if(p>lo) quick_rec(a,lo,p-1); lo=p+1; }
        else { if(hi>p) quick_rec(a,p+1,hi); if(p==0) break; hi=p-1; }
    }
}
void quicksort(int *a, size_t n){
    if(!a||n<2)return;
    quick_rec(a,0,n-1);
}

// swap_int / lomuto_partition 재사용 (문제 5 참고)
int quickselect_kth(int *a, size_t n, size_t k){
    if(!a||k>=n)return INT32_MIN;
    size_t lo=0,hi=n-1;
    while(lo<hi){
        size_t p=lomuto_partition(a,lo,hi);
        if(p==k)return a[p];
        if(k<p){ if(p==0) break; hi=p-1; }
        else lo=p+1;
    }
    return a[k];
}

void counting_sort(int *a, size_t n, int max_val){
    if(!a||n<2||max_val<0)return;
    size_t K=(size_t)max_val+1;
    size_t *cnt=calloc(K,sizeof *cnt);
    if(!cnt)return;
    for(size_t i=0;i<n;i++){
        if(a[i]<0||a[i]>max_val){ free(cnt); return; }
        cnt[a[i]]++;
    }
    size_t o=0;
    for(size_t v=0;v<K;v++)
        for(size_t c=0;c<cnt[v];c++) a[o++]=(int)v;
    free(cnt);
}

static long labs_l(long x){ return x<0?-x:x; }
int nearest_brute(const int *a,size_t n,const int *b,size_t m,
                  int *out_nearest,int *out_max_dist){
    if(!a||!b||!out_nearest||!out_max_dist||m==0)return -1;
    long max_dist=0;
    for(size_t i=0;i<n;i++){
        int best=b[0]; long bestd=labs_l((long)a[i]-b[0]);
        for(size_t j=1;j<m;j++){
            long d=labs_l((long)a[i]-b[j]);
            if(d<bestd||(d==bestd&&b[j]>best)){ bestd=d; best=b[j]; }
        }
        out_nearest[i]=best;
        if(bestd>max_dist) max_dist=bestd;
    }
    *out_max_dist=(int)max_dist; return 0;
}
static size_t lb_sorted(const int *s,size_t len,int x){
    size_t lo=0,hi=len;
    while(lo<hi){ size_t mid=lo+(hi-lo)/2; if(s[mid]<x) lo=mid+1; else hi=mid; }
    return lo;
}
int nearest_fast(const int *a,size_t n,const int *b,size_t m,
                 int *out_nearest,int *out_max_dist){
    if(!a||!b||!out_nearest||!out_max_dist||m==0)return -1;
    int *sb=malloc(m*sizeof *sb);
    if(!sb)return -1;
    memcpy(sb,b,m*sizeof *sb);
    quicksort(sb,m);                       // O(m log m)
    long max_dist=0;
    for(size_t i=0;i<n;i++){
        size_t pos=lb_sorted(sb,m,a[i]);   // O(log m)
        int best; long bestd;
        if(pos==m){ best=sb[m-1]; bestd=labs_l((long)a[i]-best); }
        else {
            best=sb[pos]; bestd=labs_l((long)a[i]-best);
            if(pos>0){ long ld=labs_l((long)a[i]-sb[pos-1]);
                if(ld<bestd){ bestd=ld; best=sb[pos-1]; } }
        }
        out_nearest[i]=best;
        if(bestd>max_dist) max_dist=bestd;
    }
    *out_max_dist=(int)max_dist; free(sb); return 0;
}

void insertion_sort(int *a, size_t n){
    if(!a||n<2)return;
    for(size_t i=1;i<n;i++){
        int key=a[i]; size_t j=i;
        while(j>0&&a[j-1]>key){ a[j]=a[j-1]; j--; }
        a[j]=key;
    }
}
